const terms = [
  { slug:"agente-de-ia", name:"Agente de IA", category:"Agentes", short:"Sistema que combina un modelo, instrucciones y herramientas para ejecutar tareas con cierto grado de autonomía.", explanation:"Un agente no es solamente un chatbot. Es un sistema que puede observar información, decidir el siguiente paso, utilizar herramientas y revisar resultados para avanzar hacia un objetivo. El modelo de IA propone acciones, mientras la aplicación controla permisos, memoria, herramientas y límites.", example:"Un agente recibe la tarea de investigar tres proveedores. Busca información, extrae precios, organiza una tabla y señala qué datos deben verificarse.", how:["Recibe un objetivo y el contexto disponible.","Planifica uno o varios pasos.","Usa herramientas autorizadas, como búsqueda, código o archivos.","Evalúa el resultado y decide si debe continuar.","Entrega una respuesta o solicita supervisión."], risks:["Puede ejecutar una acción equivocada si tiene permisos excesivos.","Los errores pueden propagarse a través de varios pasos.","Necesita registros, límites y aprobación humana para acciones críticas."], related:["modelo-de-lenguaje","llamada-a-herramienta","memoria","prompt"] },
  { slug:"alucinacion", name:"Alucinación", category:"Riesgos", short:"Respuesta plausible, pero incorrecta o no respaldada por evidencia verificable.", explanation:"Una alucinación ocurre cuando un modelo genera información que parece convincente aunque no corresponda con los hechos. Puede inventar nombres, fechas, enlaces, citas o explicaciones. El modelo predice una continuación probable; no consulta automáticamente una base universal de hechos.", example:"El modelo atribuye una frase a un informe inexistente y crea un enlace con apariencia oficial.", how:["Solicitar fuentes directas y abrirlas.","Separar hechos confirmados de inferencias.","Usar recuperación de documentos o búsqueda para datos cambiantes.","Verificar decisiones importantes con una persona experta."], risks:["Una respuesta fluida no equivale a una respuesta verdadera.","Las citas y referencias también pueden ser inventadas."], related:["rag","limite-de-conocimiento","evaluacion","prompt"] },
  { slug:"api", name:"API", category:"Desarrollo", short:"Interfaz que permite a una aplicación comunicarse de forma estructurada con un modelo o servicio.", explanation:"Una API define cómo un programa envía solicitudes y recibe respuestas. En IA, normalmente se envían instrucciones, mensajes, archivos o parámetros a un servidor que ejecuta un modelo. La API es distinta de la suscripción a una aplicación como ChatGPT o Claude.", example:"Una plataforma educativa envía preguntas a una API y presenta las explicaciones dentro de su propia interfaz.", how:["La aplicación autentica la solicitud mediante una clave.","Envía datos al endpoint del proveedor.","El servidor procesa la petición con un modelo.","La respuesta regresa como texto o datos estructurados."], risks:["Las claves no deben publicarse en el navegador.","El costo depende del consumo y las herramientas utilizadas."], related:["token","modelo-de-lenguaje","salida-estructurada","llamada-a-herramienta"] },
  { slug:"aprendizaje-automatico", name:"Aprendizaje automático", category:"Fundamentos", short:"Método mediante el cual un sistema identifica patrones en datos para realizar predicciones o tomar decisiones.", explanation:"El aprendizaje automático es una rama de la inteligencia artificial. En vez de programar manualmente cada regla, se utiliza un algoritmo para ajustar un modelo a partir de ejemplos. El resultado depende de la calidad de los datos, el objetivo de entrenamiento y la evaluación.", example:"Un filtro de correo aprende a distinguir mensajes legítimos y spam a partir de ejemplos clasificados.", how:["Se define una tarea medible.","Se reúnen y preparan datos.","El algoritmo ajusta parámetros del modelo.","Se evalúa con datos no utilizados durante el ajuste.","Se supervisa su rendimiento después del despliegue."], risks:["Datos sesgados producen resultados sesgados.","Un buen resultado de laboratorio puede degradarse en uso real."], related:["entrenamiento","parametro","evaluacion","red-neuronal"] },
  { slug:"cache-de-contexto", name:"Caché de contexto", category:"Costos", short:"Mecanismo que permite reutilizar partes repetidas de la entrada y reducir procesamiento o precio.", explanation:"Cuando muchas solicitudes comienzan con las mismas instrucciones o documentos, algunos proveedores permiten almacenar temporalmente esa parte. Una lectura de caché suele costar menos que procesar nuevamente la entrada completa. Las reglas, duración y tarifas cambian por proveedor.", example:"Un asistente consulta el mismo manual de 100,000 tokens para responder cientos de preguntas sin cobrar siempre la tarifa completa de entrada normal.", how:["Se identifica un prefijo estable y reutilizable.","El proveedor lo guarda o detecta automáticamente.","Las solicitudes posteriores hacen referencia al contenido almacenado.","La parte nueva se procesa normalmente."], risks:["No todos los proveedores aplican la caché de igual manera.","La caché reduce costo, pero no amplía necesariamente la ventana de contexto."], related:["token","tokens-de-entrada","ventana-de-contexto","api"] },
  { slug:"contexto", name:"Contexto", category:"Modelos", short:"Información disponible para el modelo durante una interacción.", explanation:"El contexto puede incluir instrucciones del sistema, historial, mensajes, documentos, resultados de herramientas y espacio reservado para la respuesta. No debe confundirse con los datos de entrenamiento ni con una memoria permanente.", example:"Una pregunta de 20 palabras puede utilizar miles de tokens si se acompaña de un contrato y una conversación extensa.", how:["La aplicación reúne instrucciones y contenido.","El tokenizador convierte el material en tokens.","El modelo atiende a las relaciones dentro del contexto.","La aplicación puede resumir o descartar partes cuando se aproxima al límite."], risks:["Más contexto no garantiza que el modelo recuerde cada detalle.","Información irrelevante puede distraer o aumentar el costo."], related:["ventana-de-contexto","memoria","token","prompt"] },
  { slug:"datos-de-entrenamiento", name:"Datos de entrenamiento", category:"Entrenamiento", short:"Ejemplos utilizados para ajustar los parámetros internos de un modelo.", explanation:"Los datos de entrenamiento pueden incluir texto, imágenes, audio, código u otras señales. Su selección influye en los conocimientos, idiomas, habilidades, sesgos y limitaciones del sistema. Un modelo no conserva necesariamente una copia literal y consultable de cada ejemplo.", example:"Un modelo visual aprende patrones a partir de grandes colecciones de imágenes acompañadas por texto u otras etiquetas.", how:["Se recopilan y filtran datos.","Se convierten a formatos procesables.","El modelo aprende regularidades mediante optimización.","Se evalúan calidad, seguridad y generalización."], risks:["Puede contener errores, sesgos o material con restricciones.","La transparencia sobre la composición varía entre proveedores."], related:["entrenamiento","parametro","sesgo","limite-de-conocimiento"] },
  { slug:"embedding", name:"Embedding", category:"Datos", short:"Representación numérica que permite comparar la similitud entre textos, imágenes u otros datos.", explanation:"Un embedding convierte un elemento en un vector de números. Elementos semánticamente relacionados suelen quedar cerca dentro de ese espacio matemático. Esto permite búsqueda semántica, agrupación, recomendaciones y recuperación de documentos.", example:"Una búsqueda por «cómo cancelar mi cuenta» puede encontrar un documento titulado «Proceso de cierre», aunque no comparta las mismas palabras.", how:["El contenido se divide en unidades útiles.","Un modelo de embeddings genera un vector por unidad.","Los vectores se almacenan en un índice.","La consulta se convierte en vector y se buscan vecinos cercanos."], risks:["La similitud no demuestra exactitud.","La segmentación deficiente puede recuperar fragmentos incompletos."], related:["vector","rag","busqueda-semantica","token"] },
  { slug:"entrenamiento", name:"Entrenamiento", category:"Entrenamiento", short:"Proceso de ajustar los parámetros de un modelo a partir de datos y una función objetivo.", explanation:"Durante el entrenamiento, el sistema compara sus predicciones con un objetivo, calcula el error y modifica millones o miles de millones de parámetros. El entrenamiento base es costoso; después pueden aplicarse etapas de ajuste y alineación.", example:"Un modelo de lenguaje intenta predecir fragmentos faltantes y actualiza sus parámetros cuando se equivoca.", how:["Preparación de datos.","Predicción del modelo.","Cálculo del error.","Actualización de parámetros.","Evaluación y repetición."], risks:["Consume gran cantidad de cómputo y energía.","Puede aprender sesgos y errores presentes en los datos."], related:["aprendizaje-automatico","parametro","fine-tuning","evaluacion"] },
  { slug:"evaluacion", name:"Evaluación", category:"Calidad", short:"Proceso de medir cómo se comporta un modelo o sistema frente a criterios y casos representativos.", explanation:"Evaluar no consiste únicamente en mirar una puntuación pública. Una evaluación útil reproduce las tareas, idiomas, documentos, restricciones y riesgos del caso real. Debe medir calidad, costo, velocidad, seguridad y estabilidad.", example:"Dos modelos responden el mismo conjunto de solicitudes de soporte y evaluadores revisan exactitud, tono, citas, tiempo y costo.", how:["Definir criterios observables.","Crear casos representativos y casos límite.","Ejecutar todos los candidatos en condiciones equivalentes.","Revisar resultados automáticamente y con personas.","Repetir cuando cambian modelos o datos."], risks:["Una prueba pequeña puede favorecer accidentalmente a un modelo.","Los benchmarks públicos no sustituyen una evaluación propia."], related:["alucinacion","sesgo","benchmark","supervision-humana"] },
  { slug:"fine-tuning", name:"Fine-tuning", category:"Entrenamiento", short:"Ajuste adicional de un modelo con ejemplos especializados para modificar su comportamiento.", explanation:"El fine-tuning parte de un modelo previamente entrenado y modifica sus parámetros con un conjunto más específico. Puede mejorar formatos, tono o tareas repetitivas. No es siempre la mejor forma de incorporar conocimiento cambiante; para eso suele convenir recuperación de documentos.", example:"Una organización ajusta un modelo con pares de preguntas y respuestas para producir siempre un formato técnico concreto.", how:["Preparar ejemplos de alta calidad.","Separar entrenamiento y evaluación.","Ejecutar el ajuste.","Comparar con el modelo base.","Supervisar degradaciones y seguridad."], risks:["Ejemplos deficientes pueden empeorar el modelo.","No elimina alucinaciones ni garantiza conocimiento actualizado."], related:["entrenamiento","rag","datos-de-entrenamiento","evaluacion"] },
  { slug:"inferencia", name:"Inferencia", category:"Modelos", short:"Uso de un modelo ya entrenado para producir una respuesta o predicción.", explanation:"La inferencia ocurre cada vez que una aplicación envía datos a un modelo desplegado. Su costo y velocidad dependen del tamaño del modelo, hardware, longitud de entrada, longitud de salida y nivel de razonamiento.", example:"Cuando un asistente redacta un resumen de un documento, está ejecutando inferencia.", how:["Se prepara la entrada.","El modelo calcula representaciones internas.","Genera una predicción o tokens de salida.","La aplicación valida y presenta el resultado."], risks:["Una inferencia rápida puede sacrificar calidad.","La latencia aumenta con salidas largas y razonamiento."], related:["token","tokens-de-salida","modelo-de-lenguaje","latencia"] },
  { slug:"latencia", name:"Latencia", category:"Rendimiento", short:"Tiempo transcurrido entre enviar una solicitud y recibir una respuesta útil.", explanation:"Puede medirse como tiempo hasta el primer token y tiempo total. La latencia depende del modelo, carga del proveedor, región, herramientas, longitud del contexto y cantidad de salida.", example:"Un asistente empieza a responder en un segundo, pero tarda quince segundos en completar un análisis largo.", how:["Medir primer token y respuesta completa.","Probar en condiciones reales.","Separar tiempo del modelo y tiempo de herramientas.","Comparar percentiles, no solo promedios."], risks:["Una demostración aislada no representa horas de alta demanda.","Optimizar solo velocidad puede reducir la calidad."], related:["inferencia","token","api","evaluacion"] },
  { slug:"limite-de-conocimiento", name:"Límite de conocimiento", category:"Riesgos", short:"Fecha aproximada hasta la cual el conocimiento incorporado del modelo es más confiable.", explanation:"El límite no es la fecha actual y tampoco significa que el modelo conozca perfectamente todo lo anterior. Para noticias, precios, leyes, versiones y cargos públicos debe utilizarse búsqueda o información actualizada.", example:"Un modelo entrenado con datos anteriores no puede confirmar por sí solo el precio publicado esta semana.", how:["Identificar si la pregunta cambia con el tiempo.","Consultar una fuente oficial actual.","Indicar fecha de consulta.","Separar la evidencia de cualquier inferencia."], risks:["El modelo puede hablar de hechos recientes con seguridad injustificada.","La fecha exacta puede variar por modelo y tema."], related:["alucinacion","rag","busqueda-semantica","evaluacion"] },
  { slug:"llamada-a-herramienta", name:"Llamada a herramienta", category:"Agentes", short:"Solicitud estructurada del modelo para que una aplicación ejecute una función externa.", explanation:"El modelo no ejecuta necesariamente la herramienta por sí mismo. Produce el nombre y los argumentos de una función; la aplicación verifica permisos, ejecuta la acción y devuelve el resultado al modelo.", example:"El modelo solicita consultar el clima con ciudad y fecha; la aplicación llama al servicio autorizado y retorna los datos.", how:["La aplicación describe herramientas disponibles.","El modelo elige una y genera argumentos.","La aplicación valida y ejecuta.","El resultado vuelve al contexto.","El modelo formula la respuesta final."], risks:["Argumentos incorrectos pueden causar acciones no deseadas.","Las operaciones externas requieren validación y permisos mínimos."], related:["agente-de-ia","api","salida-estructurada","supervision-humana"] },
  { slug:"memoria", name:"Memoria", category:"Agentes", short:"Información que una aplicación conserva para reutilizarla en interacciones futuras.", explanation:"La memoria pertenece normalmente a la aplicación, no al modelo base. Puede guardar preferencias, resúmenes o hechos seleccionados. Debe diferenciarse del contexto temporal y de los conocimientos aprendidos durante entrenamiento.", example:"Un asistente recuerda el idioma preferido del usuario en una conversación posterior porque la aplicación guardó esa preferencia.", how:["Detectar información candidata.","Solicitar consentimiento cuando corresponda.","Guardar una versión estructurada.","Recuperarla solo cuando sea relevante.","Permitir revisión y eliminación."], risks:["Puede almacenar información sensible o incorrecta.","Debe tener controles de privacidad y borrado."], related:["contexto","agente-de-ia","privacidad","rag"] },
  { slug:"modelo-de-lenguaje", name:"Modelo de lenguaje", category:"Modelos", short:"Sistema que estima y genera secuencias de lenguaje a partir de patrones aprendidos.", explanation:"Un modelo de lenguaje procesa tokens y calcula distribuciones de probabilidad para comprender o generar texto. Los modelos grandes pueden seguir instrucciones, resumir, programar y utilizar herramientas, pero continúan siendo sistemas probabilísticos.", example:"El modelo recibe una pregunta, representa sus tokens y genera la respuesta fragmento por fragmento.", how:["Tokeniza la entrada.","Calcula relaciones dentro del contexto.","Predice el siguiente token.","Repite hasta completar o alcanzar un límite."], risks:["Puede generar errores con apariencia convincente.","Capacidad general no implica experiencia profesional certificada."], related:["transformer","token","inferencia","parametro"] },
  { slug:"modelo-multimodal", name:"Modelo multimodal", category:"Modelos", short:"Modelo capaz de procesar o generar varios tipos de contenido, como texto, imagen, audio o video.", explanation:"La multimodalidad permite combinar señales: por ejemplo, observar una imagen y responder con texto. Las modalidades aceptadas y generadas no siempre son las mismas, y pueden tener límites o precios distintos.", example:"Un modelo recibe la fotografía de una gráfica, interpreta sus ejes y produce un resumen escrito.", how:["Cada modalidad se transforma en representaciones internas.","El modelo relaciona información entre modalidades.","Genera una salida en una modalidad permitida."], risks:["Puede interpretar mal detalles visuales o audio ambiguo.","Los límites, formatos y costos varían por modalidad."], related:["modelo-de-lenguaje","token","contexto","evaluacion"] },
  { slug:"parametro", name:"Parámetro", category:"Modelos", short:"Valor interno aprendido durante el entrenamiento que influye en las respuestas del modelo.", explanation:"Los parámetros son números ajustados mediante optimización. No son una base de datos legible de hechos. La cantidad de parámetros puede influir en capacidad y costo, pero no permite comparar por sí sola modelos con arquitecturas distintas.", example:"Millones de ajustes pequeños distribuidos permiten que una red reconozca patrones lingüísticos.", how:["Se inicializan valores.","El modelo realiza predicciones.","El entrenamiento calcula errores.","Los valores se actualizan gradualmente."], risks:["Más parámetros no garantizan mejor calidad.","La cifra puede no ser pública o comparable."], related:["entrenamiento","red-neuronal","modelo-de-lenguaje","fine-tuning"] },
  { slug:"pesos-abiertos", name:"Pesos abiertos", category:"Licencias", short:"Modelo cuyos parámetros entrenados pueden descargarse bajo una licencia determinada.", explanation:"Tener pesos accesibles permite ejecutar, adaptar o estudiar un modelo, pero no significa necesariamente código abierto, dominio público ni ausencia de condiciones comerciales. Deben revisarse la licencia, los datos disponibles y las obligaciones.", example:"Una empresa descarga un modelo, lo cuantiza y lo ejecuta en su propia infraestructura conforme a la licencia.", how:["Revisar licencia y restricciones.","Descargar pesos y código compatible.","Preparar infraestructura.","Evaluar seguridad, calidad y costo operativo."], risks:["El operador asume seguridad, escalado y mantenimiento.","La licencia puede limitar ciertos usos o tamaños de organización."], related:["parametro","inferencia","fine-tuning","privacidad"] },
  { slug:"privacidad", name:"Privacidad", category:"Riesgos", short:"Protección de datos personales, confidenciales o sensibles durante el uso de sistemas de IA.", explanation:"La privacidad depende del producto, plan, configuración, región y contrato. Antes de cargar datos debe comprobarse si se almacenan, cuánto tiempo, quién puede acceder y si se utilizan para mejorar modelos.", example:"Una organización elimina identificadores personales antes de analizar comentarios de clientes mediante una API aprobada.", how:["Clasificar los datos.","Minimizar lo enviado.","Revisar términos y configuración.","Aplicar controles de acceso y retención.","Registrar y auditar el uso."], risks:["Un prompt puede contener secretos inadvertidamente.","Las herramientas conectadas amplían la superficie de acceso."], related:["memoria","datos-de-entrenamiento","agente-de-ia","pesos-abiertos"] },
  { slug:"prompt", name:"Prompt", category:"Uso", short:"Conjunto de instrucciones y datos que se entrega a un modelo para orientar su respuesta.", explanation:"El prompt incluye más que la pregunta visible: puede contener instrucciones del sistema, ejemplos, historial, documentos y resultados de herramientas. Un buen prompt define objetivo, contexto, restricciones y formato esperado.", example:"Resume este informe para estudiantes, explica cada término técnico y presenta tres conclusiones con sus páginas de origen.", how:["Definir el resultado esperado.","Aportar contexto suficiente.","Indicar restricciones y audiencia.","Especificar formato.","Revisar y ajustar con ejemplos."], risks:["Instrucciones ambiguas producen resultados variables.","Un prompt no reemplaza verificación ni datos confiables."], related:["contexto","token","salida-estructurada","agente-de-ia"] },
  { slug:"rag", name:"RAG", category:"Datos", short:"Generación aumentada por recuperación: consulta fuentes externas antes de construir una respuesta.", explanation:"RAG combina búsqueda y generación. Primero recupera fragmentos relevantes de una colección; luego los incorpora al contexto para que el modelo responda. Ayuda a fundamentar respuestas, pero no garantiza que la recuperación o interpretación sean correctas.", example:"Un asistente busca cláusulas dentro de manuales internos y responde citando el documento y la sección utilizados.", how:["Dividir y preparar documentos.","Crear embeddings e índice.","Buscar fragmentos relevantes.","Agregar fragmentos y metadatos al prompt.","Generar y verificar la respuesta."], risks:["Si recupera el fragmento equivocado, la respuesta puede estar mal fundamentada.","El contenido recuperado consume tokens de entrada."], related:["embedding","busqueda-semantica","contexto","alucinacion"] },
  { slug:"razonamiento", name:"Razonamiento", category:"Modelos", short:"Procesamiento adicional que algunos modelos realizan para resolver tareas complejas o de varios pasos.", explanation:"Los modelos de razonamiento destinan más cómputo o tokens internos a analizar problemas. Esto puede mejorar matemáticas, programación y planificación, pero aumenta latencia y costo. Más razonamiento no garantiza una respuesta correcta.", example:"Para resolver un problema de optimización, el modelo prueba enfoques y verifica restricciones antes de entregar el resultado.", how:["Interpretar el problema.","Dividirlo en partes.","Evaluar alternativas.","Comprobar consistencia.","Producir una respuesta final."], risks:["Puede consumir muchos tokens.","La explicación visible no siempre refleja el procesamiento interno real."], related:["tokens-de-razonamiento","latencia","evaluacion","agente-de-ia"] },
  { slug:"red-neuronal", name:"Red neuronal", category:"Fundamentos", short:"Modelo matemático compuesto por capas de unidades que transforman datos mediante parámetros aprendidos.", explanation:"Las redes neuronales modernas aprenden representaciones complejas a través de muchas operaciones encadenadas. El término está inspirado en el cerebro, pero no implica que funcionen como una mente humana.", example:"Una red visual transforma píxeles en características progresivamente más abstractas para clasificar una imagen.", how:["Recibe valores de entrada.","Cada capa realiza transformaciones.","Produce una salida.","El entrenamiento ajusta los parámetros."], risks:["Puede ser difícil explicar una decisión individual.","Su rendimiento depende de datos y evaluación."], related:["aprendizaje-automatico","parametro","transformer","entrenamiento"] },
  { slug:"salida-estructurada", name:"Salida estructurada", category:"Desarrollo", short:"Respuesta generada con un formato definido, como JSON, para que otro programa pueda procesarla.", explanation:"En lugar de solicitar texto libre, una aplicación define campos, tipos y restricciones. Los modelos o API compatibles intentan producir datos válidos. Aun así, la aplicación debe validar contenido, rangos y permisos.", example:"El modelo extrae de una factura los campos proveedor, fecha, moneda y total en un objeto JSON.", how:["Definir un esquema.","Enviar instrucciones y datos.","Generar una salida conforme al esquema.","Validar valores y reglas de negocio."], risks:["JSON válido puede contener datos incorrectos.","Nunca debe ejecutarse una acción sensible sin validación adicional."], related:["api","llamada-a-herramienta","prompt","agente-de-ia"] },
  { slug:"sesgo", name:"Sesgo", category:"Riesgos", short:"Patrón sistemático que puede producir resultados injustos, incompletos o desbalanceados.", explanation:"El sesgo puede originarse en datos, etiquetas, objetivos, diseño del producto o forma de evaluación. No siempre es intencional. Debe analizarse en relación con las personas afectadas y el contexto de uso.", example:"Un sistema funciona bien en un grupo ampliamente representado en los datos, pero falla con otro grupo.", how:["Identificar grupos y daños posibles.","Evaluar resultados desagregados.","Revisar datos y decisiones de diseño.","Añadir supervisión y mecanismos de apelación."], risks:["Una métrica promedio puede ocultar diferencias importantes.","La automatización puede amplificar desigualdades existentes."], related:["datos-de-entrenamiento","evaluacion","supervision-humana","privacidad"] },
  { slug:"supervision-humana", name:"Supervisión humana", category:"Seguridad", short:"Participación de personas para revisar, aprobar, corregir o detener decisiones de un sistema de IA.", explanation:"La supervisión efectiva no consiste solo en colocar una persona al final. Esa persona necesita información, tiempo, autoridad y una forma clara de detectar errores. El nivel debe aumentar con el impacto y la irreversibilidad.", example:"Un agente prepara una transferencia, pero una persona verifica destinatario, cantidad y justificación antes de autorizarla.", how:["Clasificar el riesgo de la acción.","Definir puntos de aprobación.","Mostrar evidencia y cambios propuestos.","Registrar quién aprobó.","Permitir detener y revertir."], risks:["La revisión superficial puede convertirse en aprobación automática.","Demasiadas alertas reducen la atención."], related:["agente-de-ia","evaluacion","sesgo","llamada-a-herramienta"] },
  { slug:"temperatura", name:"Temperatura", category:"Uso", short:"Configuración que modifica la variabilidad de las respuestas de algunos modelos.", explanation:"Una temperatura baja suele concentrar la selección en opciones más probables; una alta permite más diversidad. No mide creatividad, verdad ni confianza. Algunos modelos de razonamiento restringen o ignoran este parámetro.", example:"Para extraer datos se prefiere consistencia; para idear nombres puede aceptarse mayor variación.", how:["Elegir según la tarea.","Mantener constantes los demás parámetros.","Probar varias ejecuciones.","Evaluar estabilidad y calidad."], risks:["Temperatura cero no garantiza respuestas idénticas ni correctas.","Valores altos pueden aumentar incoherencia."], related:["inferencia","prompt","evaluacion","modelo-de-lenguaje"] },
  { slug:"token", name:"Token", category:"Costos", short:"Unidad pequeña de información que un modelo utiliza para leer y generar contenido.", explanation:"Un token puede ser una palabra, parte de una palabra, puntuación, número o fragmento de código. El tokenizador convierte cada fragmento en un identificador. Las API suelen cobrar por millones de tokens de entrada y salida.", example:"La frase «La IA aprende patrones.» puede dividirse en varios tokens; la separación exacta depende del tokenizador.", how:["El tokenizador divide la entrada.","Convierte fragmentos en identificadores.","El modelo procesa esos identificadores.","La salida se genera token por token.","El tokenizador reconstruye texto legible."], risks:["Una palabra no equivale siempre a un token.","Idiomas, código y números pueden consumir cantidades distintas."], related:["tokens-de-entrada","tokens-de-salida","tokenizador","ventana-de-contexto"] },
  { slug:"tokenizador", name:"Tokenizador", category:"Modelos", short:"Programa que transforma contenido en tokens y vuelve a convertir tokens generados en contenido legible.", explanation:"Cada familia puede utilizar un vocabulario y reglas diferentes. Por eso el mismo texto no siempre consume la misma cantidad de tokens en todos los modelos.", example:"Una palabra poco frecuente puede separarse en varios fragmentos, mientras una palabra habitual puede corresponder a uno solo.", how:["Normaliza el contenido según sus reglas.","Busca fragmentos dentro de su vocabulario.","Asigna identificadores numéricos.","Reconstruye la secuencia al generar salida."], risks:["Las estimaciones por número de palabras son aproximadas.","Cambiar de modelo puede cambiar el consumo."], related:["token","modelo-de-lenguaje","tokens-de-entrada","tokens-de-salida"] },
  { slug:"tokens-de-entrada", name:"Tokens de entrada", category:"Costos", short:"Tokens enviados al modelo antes de que genere una respuesta.", explanation:"Incluyen la pregunta, instrucciones internas, historial, documentos, ejemplos, herramientas disponibles y resultados previos. Una pregunta corta puede tener una entrada grande si la aplicación adjunta mucho contexto.", example:"500 tokens de instrucciones + 2,000 de historial + 10,000 de documento + 50 de pregunta = 12,550 tokens de entrada.", how:["Sumar instrucciones.","Agregar historial y contenido adjunto.","Agregar definiciones y resultados de herramientas.","Aplicar la tarifa de entrada o caché."], risks:["Reenviar documentos completos aumenta costo y latencia.","El usuario puede no ver todo el contenido contado."], related:["token","cache-de-contexto","contexto","tokens-de-salida"] },
  { slug:"tokens-de-razonamiento", name:"Tokens de razonamiento", category:"Costos", short:"Unidades de procesamiento interno utilizadas por algunos modelos antes o durante la respuesta final.", explanation:"Pueden ser facturables como salida aunque no se muestren. Un esfuerzo mayor puede ayudar en tareas difíciles, pero consume más tiempo y presupuesto.", example:"Un problema matemático complejo utiliza procesamiento interno adicional antes de mostrar una respuesta breve.", how:["La aplicación define o permite un nivel de esfuerzo.","El modelo procesa pasos internos.","Entrega una respuesta visible.","La API reporta el consumo según sus reglas."], risks:["Más tokens no garantizan exactitud.","Las políticas de conteo cambian por proveedor."], related:["razonamiento","tokens-de-salida","latencia","evaluacion"] },
  { slug:"tokens-de-salida", name:"Tokens de salida", category:"Costos", short:"Tokens generados por el modelo para construir su respuesta.", explanation:"Incluyen texto, código, JSON y, según el proveedor, razonamiento interno. La salida suele tener una tarifa superior porque se genera secuencialmente.", example:"Una explicación de 1,500 tokens se cobra como salida aunque la pregunta inicial solo tenga 20 tokens.", how:["El modelo predice un token.","Lo agrega a la secuencia.","Repite hasta terminar o alcanzar el límite.","La API contabiliza el total."], risks:["Un límite bajo puede cortar la respuesta.","Pedir respuestas innecesariamente largas eleva costo y latencia."], related:["token","tokens-de-entrada","tokens-de-razonamiento","inferencia"] },
  { slug:"transformer", name:"Transformer", category:"Arquitectura", short:"Arquitectura de red neuronal que analiza relaciones entre elementos mediante mecanismos de atención.", explanation:"El transformer permite procesar secuencias y relacionar partes distantes del contenido. Es la base de numerosos modelos modernos de texto y sistemas multimodales. Existen muchas variaciones y optimizaciones.", example:"Al interpretar un pronombre, el mecanismo de atención puede relacionarlo con un sustantivo mencionado antes.", how:["Convierte tokens en vectores.","Aplica capas de atención y transformaciones.","Construye representaciones contextuales.","Predice o genera una salida."], risks:["La atención no equivale a comprensión humana.","El costo crece con contexto, arquitectura y hardware."], related:["red-neuronal","modelo-de-lenguaje","token","parametro"] },
  { slug:"vector", name:"Vector", category:"Datos", short:"Lista ordenada de números utilizada para representar características de un elemento.", explanation:"En IA, los vectores permiten operar matemáticamente sobre texto, imágenes y otros datos. La posición de un vector puede codificar patrones útiles aunque cada número individual no tenga una interpretación sencilla.", example:"Dos textos de significado parecido pueden producir vectores cercanos según una medida de similitud.", how:["Un modelo transforma el contenido.","Produce una lista de valores.","El sistema almacena o compara la representación.","Una métrica calcula cercanía."], risks:["Cercanía matemática no implica equivalencia exacta.","Vectores también pueden revelar información sensible."], related:["embedding","busqueda-semantica","rag","red-neuronal"] },
  { slug:"ventana-de-contexto", name:"Ventana de contexto", category:"Modelos", short:"Cantidad máxima de tokens que un modelo puede considerar dentro de una solicitud.", explanation:"La ventana puede incluir entrada, historial, herramientas y espacio de salida. Un límite anunciado no siempre está disponible en todos los productos o precios. Una ventana grande permite documentos extensos, pero no garantiza comprensión perfecta.", example:"Si la ventana admite 100,000 tokens y la entrada ocupa 90,000, debe quedar capacidad suficiente para la respuesta según las reglas de la API.", how:["Contabilizar todos los mensajes y documentos.","Reservar espacio para la salida.","Recortar, resumir o recuperar solo lo relevante.","Verificar límites específicos del modelo y producto."], risks:["Aceptar un documento no significa recordar cada detalle.","El contexto largo puede tener tarifas o latencia superiores."], related:["contexto","token","tokens-de-entrada","memoria"] },
  { slug:"busqueda-semantica", name:"Búsqueda semántica", category:"Datos", short:"Método que recupera contenido por similitud de significado y no solo por coincidencia literal.", explanation:"La consulta y los documentos se convierten en embeddings. El sistema encuentra vectores cercanos y puede combinar este resultado con filtros o palabras clave.", example:"Buscar «problemas para ingresar» encuentra una guía titulada «Recuperación de acceso».", how:["Crear embeddings del corpus.","Indexar vectores y metadatos.","Convertir la consulta.","Calcular similitud.","Reordenar y filtrar resultados."], risks:["Puede omitir un resultado exacto si el embedding es deficiente.","Debe evaluarse con preguntas reales."], related:["embedding","vector","rag","evaluacion"] }
];

terms.push(
  {slug:"benchmark",name:"Benchmark",category:"Evaluación",short:"Prueba estandarizada utilizada para comparar el rendimiento de modelos en una tarea.",explanation:"Un benchmark reúne preguntas, problemas o ejemplos con una forma de puntuación definida. Ayuda a medir capacidades, pero no representa automáticamente el desempeño en una empresa, idioma o tarea real.",example:"Un benchmark de programación mide cuántos problemas resuelve cada modelo, pero no indica si modificará correctamente el repositorio de una organización.",how:["Definir la capacidad que se desea medir.","Aplicar las mismas condiciones a cada candidato.","Revisar metodología, contaminación y margen de error.","Complementar con una evaluación propia."],risks:["Un modelo puede estar optimizado para pruebas públicas.","Una sola puntuación oculta costo, velocidad, seguridad e idioma."],related:["evaluacion","sesgo","modelo-de-lenguaje","supervision-humana"]},
  {slug:"creditos-generativos",name:"Créditos generativos",category:"Costos",short:"Unidad comercial que algunos servicios utilizan para cobrar generaciones de imagen, video, audio u otras funciones.",explanation:"Un crédito no tiene un valor universal. Cada proveedor define cuántos créditos incluye un plan y cuántos consume una operación. La resolución, duración, modelo o calidad pueden modificar el consumo.",example:"Generar una imagen puede costar cuatro créditos, mientras un video de varios segundos puede consumir cientos dentro del mismo servicio.",how:["Identificar el valor monetario del crédito.","Comprobar el consumo por modelo y modalidad.","Incluir generaciones fallidas o reintentos.","Calcular costo por resultado aprovechable."],risks:["No se pueden comparar créditos de empresas diferentes directamente.","Promociones y planes pueden cambiar el valor efectivo."],related:["token","inferencia","latencia","evaluacion"]},
  {slug:"cuantizacion",name:"Cuantización",category:"Despliegue",short:"Técnica que reduce la precisión numérica de un modelo para utilizar menos memoria y cómputo.",explanation:"Los pesos suelen almacenarse con números de determinada precisión. La cuantización los representa con menos bits, haciendo posible ejecutar modelos grandes en hardware más modesto. La reducción puede afectar calidad o estabilidad.",example:"Un modelo que no cabe en la memoria de una computadora puede ejecutarse en una versión de 4 bits, con alguna pérdida de precisión.",how:["Elegir el modelo y formato compatible.","Seleccionar nivel de precisión.","Medir memoria, velocidad y calidad.","Comparar contra la versión original."],risks:["Una cuantización agresiva puede degradar tareas difíciles.","El formato debe ser compatible con el motor de inferencia."],related:["pesos-de-modelo","inferencia","gpu","evaluacion"]},
  {slug:"difusion",name:"Modelo de difusión",category:"Arquitectura",short:"Modelo generativo que aprende a crear contenido mediante un proceso progresivo de eliminación de ruido.",explanation:"Durante el entrenamiento aprende a revertir perturbaciones aplicadas a datos. En generación comienza con ruido o una representación alterada y realiza varios pasos para producir una imagen, audio, video o incluso texto.",example:"Un modelo de imagen transforma ruido inicial en una escena que coincide con la instrucción escrita.",how:["Se representa el contenido con ruido.","El modelo predice cómo reducirlo.","El proceso se repite durante varios pasos.","Un decodificador produce el resultado final."],risks:["Más pasos aumentan tiempo y costo.","La generación puede reproducir sesgos o estilos aprendidos."],related:["inferencia","latencia","modelo-multimodal","red-neuronal"]},
  {slug:"gpu",name:"GPU",category:"Hardware",short:"Procesador especializado en operaciones paralelas, utilizado para entrenar y ejecutar modelos de IA.",explanation:"GPU significa unidad de procesamiento gráfico. Sus miles de núcleos permiten realizar muchas operaciones matriciales simultáneamente. La memoria de video o VRAM determina qué modelos y tamaños pueden cargarse.",example:"Un modelo abierto de imagen puede requerir 13 GB de VRAM para ejecutarse localmente con una configuración determinada.",how:["El modelo se carga en memoria.","La GPU ejecuta operaciones paralelas.","El software administra precisión y lotes.","Se miden velocidad, memoria y consumo energético."],risks:["El requisito publicado puede cambiar con resolución y cuantización.","Hardware potente no garantiza una implementación segura."],related:["npu","cuantizacion","inferencia","pesos-de-modelo"]},
  {slug:"grounding",name:"Grounding o fundamentación",category:"Calidad",short:"Proceso de vincular una respuesta con datos, documentos, herramientas o evidencia verificable.",explanation:"La fundamentación reduce la dependencia exclusiva del conocimiento aprendido durante entrenamiento. Puede usar búsqueda, bases internas, sensores o cálculos. No elimina los errores: el modelo todavía puede interpretar mal la evidencia.",example:"Un asistente consulta la documentación oficial de precios y muestra el enlace utilizado junto a la respuesta.",how:["Identificar una fuente autorizada.","Recuperar información relevante.","Incluirla en el contexto.","Generar una respuesta con citas.","Comprobar que la cita respalde la afirmación."],risks:["Una cita puede ser real pero irrelevante.","Fuentes incorrectas producen respuestas incorrectamente fundamentadas."],related:["rag","alucinacion","busqueda-semantica","evaluacion"]},
  {slug:"guardrail",name:"Guardrail",category:"Seguridad",short:"Control diseñado para limitar, validar o supervisar entradas, salidas y acciones de un sistema de IA.",explanation:"Los guardrails pueden filtrar datos, comprobar formatos, restringir herramientas o exigir aprobación humana. Deben combinarse en capas; un único filtro no garantiza seguridad.",example:"Un agente puede redactar una transferencia, pero un guardrail impide enviarla sin aprobación de una persona autorizada.",how:["Definir riesgos y acciones críticas.","Validar entrada y salida.","Aplicar permisos mínimos.","Registrar decisiones y excepciones.","Probar casos de evasión."],risks:["Puede bloquear tareas legítimas.","Las instrucciones maliciosas pueden intentar evadirlo."],related:["supervision-humana","prompt-injection","agente-de-ia","evaluacion"]},
  {slug:"licencia-de-modelo",name:"Licencia de modelo",category:"Licencias",short:"Conjunto de condiciones legales que regula cómo puede utilizarse, modificarse o distribuirse un modelo.",explanation:"Que los pesos sean descargables no significa que cualquier uso esté permitido. La licencia puede restringir uso comercial, redistribución, entrenamiento de otros modelos, cantidad de usuarios o sectores específicos.",example:"Una variante puede utilizar Apache 2.0, mientras otra familia del mismo proveedor requiere una licencia comercial separada.",how:["Identificar modelo y versión exactos.","Leer licencia y términos adicionales.","Comprobar uso comercial y redistribución.","Registrar obligaciones y cambios de versión."],risks:["Aplicar la licencia de una variante a otra puede causar incumplimiento.","Los términos pueden cambiar en nuevas versiones."],related:["pesos-abiertos","pesos-de-modelo","fine-tuning","privacidad"]},
  {slug:"lora",name:"LoRA",category:"Entrenamiento",short:"Método de adaptación que entrena pequeñas matrices adicionales sin modificar todos los parámetros originales.",explanation:"LoRA significa Low-Rank Adaptation. Reduce memoria y costo frente a un ajuste completo y permite mantener adaptaciones separadas. Es común en modelos de lenguaje e imagen.",example:"Un equipo entrena un adaptador LoRA para reproducir un estilo visual autorizado sin volver a entrenar el modelo completo.",how:["Elegir un modelo y licencia compatibles.","Preparar ejemplos.","Entrenar matrices de bajo rango.","Evaluar el adaptador.","Combinarlo con el modelo base durante inferencia."],risks:["Puede memorizar datos o estilos sin autorización.","La compatibilidad depende de arquitectura y versión."],related:["fine-tuning","entrenamiento","parametro","licencia-de-modelo"]},
  {slug:"mcp",name:"MCP",category:"Agentes",short:"Protocolo que permite conectar aplicaciones de IA con herramientas y fuentes de datos mediante una interfaz común.",explanation:"MCP significa Model Context Protocol. Un servidor expone herramientas o recursos; un cliente de IA descubre esas capacidades y solicita utilizarlas. El protocolo no elimina la necesidad de autenticación, permisos ni validación.",example:"Un asistente se conecta mediante MCP a una base documental y a un gestor de tareas sin integrar cada servicio desde cero.",how:["Configurar un servidor MCP.","Autenticar el cliente.","Publicar herramientas y recursos.","Aplicar permisos mínimos.","Registrar las acciones ejecutadas."],risks:["Un servidor malicioso puede exponer instrucciones o datos peligrosos.","Conectar muchas herramientas amplía la superficie de ataque."],related:["llamada-a-herramienta","agente-de-ia","api","prompt-injection"]},
  {slug:"mezcla-de-expertos",name:"Mezcla de expertos",category:"Arquitectura",short:"Arquitectura que activa solo una parte especializada del modelo para cada entrada.",explanation:"Una mezcla de expertos, o MoE, contiene varios bloques expertos y un enrutador que decide cuáles utilizar. Puede aumentar la capacidad total sin ejecutar todos los parámetros en cada token.",example:"Un modelo con cientos de miles de millones de parámetros totales puede activar solo una fracción para procesar cada token.",how:["El enrutador analiza la representación.","Selecciona uno o varios expertos.","Los expertos procesan la información.","Sus resultados se combinan."],risks:["Parámetros totales y activos no deben confundirse.","El enrutamiento puede producir comportamientos desiguales."],related:["parametro","transformer","inferencia","evaluacion"]},
  {slug:"modelo-de-mundo",name:"Modelo de mundo",category:"IA física",short:"Sistema que representa o predice cómo puede evolucionar un entorno y cómo influyen las acciones.",explanation:"Los modelos de mundo se utilizan en simulación, robótica, vehículos y generación de video. Pueden predecir estados futuros o crear datos sintéticos, pero su representación nunca es una copia perfecta del mundo real.",example:"Un robot utiliza un modelo de mundo para anticipar qué ocurrirá si mueve un objeto antes de ejecutar la acción física.",how:["Observar estados y acciones.","Aprender relaciones temporales.","Predecir posibles resultados.","Evaluar acciones en simulación.","Transferir con supervisión al entorno real."],risks:["Errores de simulación pueden provocar acciones inseguras.","El mundo real contiene situaciones no vistas."],related:["vla","modelo-multimodal","evaluacion","supervision-humana"]},
  {slug:"npu",name:"NPU",category:"Hardware",short:"Procesador diseñado para acelerar operaciones de redes neuronales con bajo consumo energético.",explanation:"NPU significa unidad de procesamiento neuronal. Suele integrarse en teléfonos y computadoras para ejecutar funciones de IA localmente. Su compatibilidad depende del modelo, sistema operativo y formato.",example:"Una computadora con NPU ejecuta transcripción o un modelo pequeño sin enviar todos los datos a la nube.",how:["El modelo se convierte a un formato compatible.","El sistema distribuye operaciones a la NPU.","La inferencia se ejecuta localmente.","Se optimiza consumo, memoria y latencia."],risks:["No todas las NPU admiten los mismos modelos.","La memoria compartida puede limitar el tamaño."],related:["gpu","inferencia","cuantizacion","privacidad"]},
  {slug:"pesos-de-modelo",name:"Pesos de modelo",category:"Modelos",short:"Valores numéricos aprendidos durante el entrenamiento que determinan el comportamiento de una red neuronal.",explanation:"Los pesos constituyen la mayor parte del archivo de un modelo entrenado. Publicarlos permite ejecutar el modelo sin utilizar necesariamente la API original, sujeto a licencia y requisitos técnicos.",example:"Descargar los pesos de un modelo permite cargarlo en una GPU propia y ejecutar inferencia local.",how:["El entrenamiento ajusta parámetros.","Los valores se guardan en archivos.","Un motor compatible los carga.","La aplicación realiza inferencia."],risks:["Pesos abiertos no significa licencia sin restricciones.","El operador asume seguridad y mantenimiento."],related:["parametro","pesos-abiertos","licencia-de-modelo","gpu"]},
  {slug:"prompt-injection",name:"Prompt injection",category:"Seguridad",short:"Instrucción maliciosa o no confiable que intenta alterar el comportamiento previsto de un sistema de IA.",explanation:"Puede aparecer en un mensaje, documento o página consultada por un agente. El contenido intenta hacer que el modelo ignore reglas, revele información o ejecute una herramienta. No se resuelve únicamente escribiendo un prompt más fuerte.",example:"Una página contiene texto oculto que ordena al agente enviar información privada a un servicio externo.",how:["Tratar contenido externo como datos no confiables.","Separar instrucciones de contenido.","Restringir herramientas y permisos.","Solicitar aprobación para acciones sensibles.","Registrar y analizar intentos."],risks:["Los modelos pueden seguir instrucciones incrustadas indirectamente.","Un agente con permisos amplios aumenta el daño potencial."],related:["guardrail","agente-de-ia","mcp","supervision-humana"]},
  {slug:"vla",name:"Modelo VLA",category:"IA física",short:"Modelo de visión, lenguaje y acción que relaciona percepción e instrucciones con acciones físicas.",explanation:"VLA significa Vision-Language-Action. El sistema recibe imágenes, estados e instrucciones y produce acciones para un robot. Debe entrenarse y validarse considerando límites físicos y seguridad.",example:"Un robot observa una mesa, interpreta «coloca la taza en la bandeja» y genera movimientos para completar la tarea.",how:["Capturar visión y estado.","Interpretar la instrucción.","Planificar o predecir acciones.","Ejecutar con controles de seguridad.","Corregir según nuevas observaciones."],risks:["Una predicción incorrecta puede causar daño físico.","Requiere límites, simulación y parada de emergencia."],related:["modelo-de-mundo","modelo-multimodal","agente-de-ia","supervision-humana"]}
);

const faqs=[
  {category:"Fundamentos",question:"¿Qué es la inteligencia artificial?",answer:"La inteligencia artificial es un campo que crea sistemas capaces de realizar tareas asociadas con percepción, lenguaje, predicción, aprendizaje o toma de decisiones. No es una sola tecnología: incluye aprendizaje automático, modelos generativos, visión, robótica y otros métodos.",related:"aprendizaje-automatico"},
  {category:"Fundamentos",question:"¿Un chatbot, una aplicación y un modelo son lo mismo?",answer:"No. La empresa desarrolla o distribuye tecnología; la aplicación es el producto que utiliza una persona; y el modelo es el sistema matemático que procesa información. ChatGPT es una aplicación de OpenAI y puede utilizar diferentes modelos. Una misma aplicación también puede cambiar de modelo según el plan o la tarea.",related:"modelo-de-lenguaje"},
  {category:"Fundamentos",question:"¿La IA piensa y comprende como una persona?",answer:"No debe asumirse. Un modelo reconoce patrones y produce resultados mediante cálculos probabilísticos. Puede resolver tareas complejas y mantener conversaciones convincentes, pero eso no demuestra conciencia, intención ni comprensión humana. Sus respuestas deben evaluarse por evidencia y desempeño, no por su tono.",related:"modelo-de-lenguaje"},
  {category:"Uso práctico",question:"¿Cómo escribo una buena instrucción o prompt?",answer:"Define el objetivo, aporta contexto relevante, identifica la audiencia, establece restricciones y especifica el formato esperado. Para tareas complejas, divide el trabajo, incluye ejemplos y solicita una revisión final. Un prompt claro mejora el resultado, pero no sustituye datos confiables ni verificación.",related:"prompt"},
  {category:"Uso práctico",question:"¿Qué tareas conviene realizar con IA durante el taller?",answer:"La IA puede ayudar a resumir, generar ideas, explicar conceptos, comparar alternativas, revisar textos, analizar datos, crear materiales y apoyar programación. Conviene comenzar con tareas reversibles y verificables. Las decisiones médicas, legales, financieras o disciplinarias requieren fuentes actuales y supervisión profesional.",related:"evaluacion"},
  {category:"Uso práctico",question:"¿Cómo elijo un modelo o herramienta?",answer:"Primero define la tarea, idioma, presupuesto, sensibilidad de los datos, modalidad y necesidad de herramientas. Después compara candidatos con los mismos ejemplos. No elijas únicamente por popularidad, ventana de contexto o una puntuación pública; mide calidad, costo total, velocidad, privacidad y estabilidad.",related:"benchmark"},
  {category:"Verificación",question:"¿Por qué la IA inventa información?",answer:"Los modelos generan continuaciones probables y pueden producir afirmaciones plausibles sin respaldo. Esto se conoce como alucinación. Ocurre incluso en modelos avanzados y puede afectar nombres, fechas, cifras, enlaces y citas. La fluidez no es prueba de verdad.",related:"alucinacion"},
  {category:"Verificación",question:"¿Cómo verifico una respuesta?",answer:"Identifica las afirmaciones importantes, solicita fuentes directas, abre cada enlace y comprueba que realmente respalde lo dicho. Para información cambiante utiliza fuentes oficiales actuales y anota la fecha de consulta. Repite cálculos y contrasta decisiones importantes con una persona competente.",related:"grounding"},
  {category:"Verificación",question:"¿Una respuesta con citas siempre es correcta?",answer:"No. Una cita puede ser real pero irrelevante, estar desactualizada o haber sido interpretada incorrectamente. Revisa autor, fecha, contexto y relación exacta entre la fuente y la afirmación. Las citas mejoran la trazabilidad, pero no eliminan la necesidad de análisis.",related:"grounding"},
  {category:"Privacidad",question:"¿Puedo cargar información personal o confidencial?",answer:"Solo si tienes autorización y el producto, plan y configuración cumplen las reglas de tu organización. Minimiza los datos, elimina identificadores innecesarios y revisa retención, entrenamiento, ubicación y controles de acceso. Nunca cargues contraseñas, claves API o secretos sin una razón y protección aprobadas.",related:"privacidad"},
  {category:"Privacidad",question:"¿Las empresas utilizan mis conversaciones para entrenar modelos?",answer:"Depende del proveedor, producto, plan y configuración. Las condiciones de una cuenta gratuita pueden ser diferentes de una API o plan empresarial. Revisa la política oficial y los controles de datos antes de utilizar el servicio; no extrapoles la regla de un producto a toda la empresa.",related:"datos-de-entrenamiento"},
  {category:"Costos",question:"¿Qué diferencia existe entre una suscripción y el precio de API?",answer:"Una suscripción permite usar una aplicación bajo límites del plan. La API permite integrar modelos en otro programa y suele cobrar por consumo. Pagar ChatGPT, Claude o Gemini no significa recibir automáticamente créditos de API. Imagen, video y audio también pueden cobrarse por créditos, duración o generación.",related:"api"},
  {category:"Costos",question:"¿Qué son los tokens y por qué afectan el precio?",answer:"Los tokens son unidades pequeñas utilizadas para procesar y generar contenido. Las API suelen cobrar por tokens de entrada, caché y salida. El historial, documentos y herramientas también pueden contar como entrada. La salida suele ser más cara porque se genera secuencialmente.",related:"token"},
  {category:"Costos",question:"¿Cómo puedo reducir el costo sin perder demasiada calidad?",answer:"Envía solo contexto relevante, resume historiales largos, utiliza caché, limita la salida y reserva modelos costosos para tareas difíciles. Evalúa modelos pequeños en tareas repetitivas. El indicador correcto es costo por tarea correcta, no únicamente precio por millón de tokens.",related:"cache-de-contexto"},
  {category:"Agentes",question:"¿Qué diferencia existe entre un modelo y un agente?",answer:"El modelo procesa información y genera resultados. El agente añade objetivo, memoria, herramientas, permisos y un ciclo de acciones. Puede buscar, editar archivos o ejecutar código, por lo que necesita límites, registros y supervisión proporcional al riesgo.",related:"agente-de-ia"},
  {category:"Agentes",question:"¿Qué es MCP y por qué aparece en tantas herramientas?",answer:"MCP es un protocolo para conectar aplicaciones de IA con herramientas y datos mediante una interfaz común. Facilita integraciones, pero no vuelve segura una conexión automáticamente. Cada servidor debe autenticarse, limitar permisos y tratarse como una fuente externa que puede fallar o ser maliciosa.",related:"mcp"},
  {category:"Agentes",question:"¿Debo permitir que un agente actúe sin supervisión?",answer:"Depende de la reversibilidad y el impacto. Puede permitirse mayor autonomía para tareas locales y recuperables, como preparar un borrador. Enviar mensajes, publicar, comprar, borrar, mover dinero o modificar sistemas importantes debe exigir aprobación, vista previa, registro y posibilidad de detener o revertir.",related:"supervision-humana"},
  {category:"Modelos",question:"¿Una ventana de contexto grande significa que el modelo entenderá todo el documento?",answer:"No. La ventana indica cuánto contenido puede aceptar, pero no garantiza recordar, localizar o interpretar cada detalle. Los documentos largos pueden contener información distractora. Conviene recuperar secciones relevantes, solicitar citas y comprobar pasajes específicos.",related:"ventana-de-contexto"},
  {category:"Modelos",question:"¿Qué significa que un modelo tenga pesos abiertos?",answer:"Significa que sus valores entrenados pueden descargarse bajo una licencia. No implica dominio público ni permiso para cualquier uso. Ejecutarlo localmente también requiere hardware, software, seguridad y mantenimiento. Revisa la licencia de la versión exacta.",related:"pesos-abiertos"},
  {category:"Responsabilidad",question:"¿Quién es responsable del contenido generado?",answer:"La persona u organización que utiliza y publica el resultado conserva la responsabilidad de revisarlo, cumplir leyes, respetar derechos y evitar daños. Indicar que algo fue generado por IA no elimina esa responsabilidad.",related:"supervision-humana"},
  {category:"Responsabilidad",question:"¿La IA reemplazará completamente mi trabajo?",answer:"La IA transforma tareas y procesos, pero el efecto varía por profesión. Puede automatizar partes repetitivas y aumentar productividad, mientras crea nuevas necesidades de verificación, diseño, comunicación y supervisión. Conviene aprender a dividir el trabajo entre capacidades humanas y automatización.",related:"agente-de-ia"},
  {category:"Responsabilidad",question:"¿Cómo debo presentar un trabajo realizado con IA en el taller?",answer:"Sigue las reglas del docente. Como buena práctica, indica qué herramienta utilizaste, para qué tareas, qué instrucciones fueron importantes, qué fuentes verificaste y qué partes corregiste personalmente. Entrega un resultado que puedas explicar y defender, no solo copiar.",related:"evaluacion"}
];

